function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit'
  }).format(date);
}

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function fmtDate(v) {
  if (!v) return '-';
  const d = new Date(v);
  if (isNaN(d.getTime())) return '-';
  return d.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
function fmtDateOnly(v) {
  if (!v) return '-';
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v).slice(0, 10);
  return d.toISOString().slice(0, 10);
}

const watchlistTicker = $('DB: Watchlist fuer Formular laden').all().map(i => i.json).filter(j => j && j.ticker).map(j => j.ticker);
const runs = $('DB: Simulationslaeufe laden').all().map(i => i.json).filter(j => j && j.id);
const metricsRows = $input.all().map(i => i.json).filter(j => j && j.simulation_run_id);

const metricsByRun = {};
for (const m of metricsRows) metricsByRun[m.simulation_run_id] = m;

const STATUS_LABEL = {
  draft: 'Entwurf', queued: 'wartet', running: 'laeuft', pausing: 'pausiert (wird beendet)',
  paused: 'pausiert', completed: 'abgeschlossen', completed_with_warnings: 'abgeschlossen (mit Warnungen)',
  failed: 'fehlgeschlagen', cancelled: 'abgebrochen'
};

const runsHtml = runs.map(r => {
  const prog = r.progress_total > 0 ? Math.round(100 * (r.progress_completed || 0) / r.progress_total) : 0;
  const m = metricsByRun[r.id];
  const statusLabel = STATUS_LABEL[r.status] || esc(r.status);
  const canPause = ['queued', 'running'].includes(r.status);
  const canResume = r.status === 'paused';
  const canCancel = ['draft', 'queued', 'running', 'pausing', 'paused'].includes(r.status);

  function actionForm(action, label) {
    return '<form method="post" action="/webhook/historische-simulation" style="display:inline;">' +
      '<input type="hidden" name="action" value="' + action + '">' +
      '<input type="hidden" name="run_id" value="' + esc(r.id) + '">' +
      '<button type="submit">' + label + '</button></form>';
  }

  return '<tr>' +
    '<td>' + esc(r.id) + '</td>' +
    '<td>' + esc(r.name || '-') + '</td>' +
    '<td>' + esc(fmtDateOnly(r.start_date)) + ' - ' + esc(fmtDateOnly(r.end_date)) + '</td>' +
    '<td><span class="badge">' + statusLabel + '</span></td>' +
    '<td>' + prog + '% (' + esc(fmtDateOnly(r.current_simulation_date)) + ')' + '</td>' +
    '<td>' + (m ? (Number(m.total_return_pct).toFixed(2) + '% / DD ' + Number(m.max_drawdown_pct).toFixed(2) + '% / ' + m.trade_count + ' Trades / WinRate ' + Number(m.win_rate_pct).toFixed(1) + '%') : '-') + '</td>' +
    '<td>' + fmtDate(r.last_heartbeat) + '</td>' +
    '<td>' +
      (canPause ? actionForm('pause', 'Pausieren') : '') +
      (canResume ? actionForm('resume', 'Fortsetzen') : '') +
      (canCancel ? actionForm('cancel', 'Abbrechen') : '') +
    '</td>' +
  '</tr>';
}).join('');

const prefillInstruments = watchlistTicker.join(', ');

const html = '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8">' +
  '<title>Historische Simulation (Walk-Forward)</title>' +
  '<style>' +
  'body{font-family:sans-serif;background:#1a1a1a;color:#e0e0e0;padding:24px;}' +
  'h1{color:#fff;} table{border-collapse:collapse;width:100%;margin-top:12px;}' +
  'th,td{border:1px solid #444;padding:6px 10px;text-align:left;font-size:13px;}' +
  'th{background:#2a2a2a;} .badge{background:#333;padding:2px 8px;border-radius:4px;}' +
  'form.import-form{background:#232323;padding:16px;border-radius:8px;margin-bottom:24px;max-width:700px;}' +
  'label{display:block;margin-top:10px;font-size:13px;color:#aaa;}' +
  'input[type=text],input[type=date],input[type=number]{width:100%;padding:6px;background:#1a1a1a;color:#e0e0e0;border:1px solid #444;border-radius:4px;}' +
  'button{margin-top:12px;padding:8px 16px;background:#2d6cdf;color:#fff;border:none;border-radius:4px;cursor:pointer;}' +
  '.hint{font-size:12px;color:#888;margin-top:4px;}' +
  '</style></head><body>' +
  '<h1>Historische Simulation (Walk-Forward, Pilot ohne Nachrichten)</h1>' +
  '<div class="hint">Voraussetzung: Kursdaten fuer die gewaehlten Instrumente + Zeitraum muessen bereits ueber Workflow 15 importiert sein.</div>' +
  '<form class="import-form" method="post" action="/webhook/historische-simulation">' +
    '<input type="hidden" name="action" value="create_run">' +
    '<label>Name</label>' +
    '<input type="text" name="name" placeholder="z.B. Pilot 2022-2023" required>' +
    '<label>Instrumente (Komma-getrennt)</label>' +
    '<input type="text" name="instruments" value="' + esc(prefillInstruments) + '" required>' +
    '<label>Startdatum</label>' +
    '<input type="date" name="start_date" required>' +
    '<label>Enddatum</label>' +
    '<input type="date" name="end_date" required>' +
    '<label>Startkapital (EUR)</label>' +
    '<input type="number" name="initial_capital" value="100000" min="1000" step="1000" required>' +
    '<label><input type="checkbox" name="news_enabled" value="true" style="width:auto;display:inline;"> Historische Nachrichten einbeziehen (news_event-Signal + Widerspruechliche-News-Veto)</label>' +
    '<div class="hint">Setzt voraus, dass fuer den Zeitraum bereits historische Nachrichten importiert+bewertet wurden (Workflow 16/16b).</div>' +
    '<label>Lauf-Art</label>' +
    '<select name="run_type">' +
      '<option value="walk_forward">Walk-Forward (explorativ, alle Strategien gemischt)</option>' +
      '<option value="out_of_sample">Out-of-Sample (Bestaetigung einer einzelnen Strategie)</option>' +
    '</select>' +
    '<label>Strategie-Filter (Pflicht bei Out-of-Sample)</label>' +
    '<select name="strategy_filter">' +
      '<option value="">Alle Strategien (nur fuer Walk-Forward sinnvoll)</option>' +
      '<option value="mean_reversion">mean_reversion</option>' +
      '<option value="trend_following">trend_following</option>' +
      '<option value="breakout">breakout</option>' +
      '<option value="news_event">news_event</option>' +
    '</select>' +
    '<div class="hint">Ein Out-of-Sample-Lauf bestaetigt gegenueber 09 (Lernagent Handelsstrategien) genau die hier gewaehlte Strategie fuer diesen Zeitraum - derselbe Zeitraum kann fuer dieselbe Strategie nicht zweimal als Out-of-Sample verwendet werden.</div>' +
    '<button type="submit">Simulation starten</button>' +
  '</form>' +
  '<h2>Bisherige Laeufe</h2>' +
  '<table><tr><th>ID</th><th>Name</th><th>Zeitraum</th><th>Status</th><th>Fortschritt</th><th>Ergebnis</th><th>Letzter Heartbeat</th><th>Aktionen</th></tr>' +
  runsHtml +
  '</table>' +
  '</body></html>';

return [{ json: { html } }];

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }
function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit'
  }).format(date);
}

// Aktions-Whitelist-Pattern, identisch zu Workflow 15/16. Zeitraum wird beim Run-Start in
// simulation_run_steps zerlegt (ein Schritt pro Werktag Mo-Fr - Feiertage werden vom Worker
// selbst uebersprungen, wenn an dem Tag fuer kein Instrument eine Kerze existiert).

const ALLOWED_ACTIONS = new Set(['create_run', 'pause', 'resume', 'cancel']);
const MAX_INSTRUMENTS = 30;
const TICKER_REGEX = /^[A-Za-z0-9.\-^=]{1,20}$/;

const body = $input.item.json.body || $input.item.json;
const action = String(body.action || '').trim();

if (!ALLOWED_ACTIONS.has(action)) {
  return { json: { _error: 'Unbekannte Aktion: ' + action, sql: null } };
}

function randHex(n) {
  let s = '';
  for (let i = 0; i < n; i++) s += Math.floor(Math.random() * 16).toString(16);
  return s;
}

let sql = '';
let responseInfo = { action };

if (action === 'create_run') {
  const name = String(body.name || '').trim().slice(0, 200);
  const startDate = String(body.start_date || '').trim();
  const endDate = String(body.end_date || '').trim();
  const initialCapital = Number(body.initial_capital);
  const newsEnabled = body.news_enabled === 'true' || body.news_enabled === true;
  const ALLOWED_STRATEGIES = new Set(['mean_reversion', 'trend_following', 'breakout', 'news_event']);
  const runType = body.run_type === 'out_of_sample' ? 'out_of_sample' : 'walk_forward';
  const rawStrategyFilter = String(body.strategy_filter || '').trim();
  const strategyFilter = ALLOWED_STRATEGIES.has(rawStrategyFilter) ? rawStrategyFilter : null;
  // 09b (Lernagent Handelsstrategien) bestaetigt laut eigenem Code-Kommentar bewusst KEINE
  // einzelne Strategie durch einen Lauf ohne strategy_filter ("ein globaler Baseline-Test") -
  // ein Out-of-Sample-Lauf ohne strategy_filter waere deshalb wirkungslos, nicht nur unvollstaendig.
  if (runType === 'out_of_sample' && !strategyFilter) {
    return { json: { _error: 'Out-of-Sample-Laeufe brauchen eine einzelne Strategie (strategy_filter) - sonst bestaetigt der Lauf laut 09b keine einzelne Strategie.', sql: null } };
  }

  if (!name) return { json: { _error: 'Name fehlt.', sql: null } };
  if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate) || !/^\d{4}-\d{2}-\d{2}$/.test(endDate)) {
    return { json: { _error: 'Start-/Enddatum fehlt oder ungueltiges Format (YYYY-MM-DD).', sql: null } };
  }
  if (endDate < startDate) return { json: { _error: 'Enddatum liegt vor dem Startdatum.', sql: null } };
  if (!Number.isFinite(initialCapital) || initialCapital < 1000) {
    return { json: { _error: 'Startkapital ungueltig (mindestens 1000).', sql: null } };
  }

  const rawInstruments = String(body.instruments || '').split(',').map(s => s.trim()).filter(Boolean);
  const seen = new Set();
  const instruments = [];
  const invalidInstruments = [];
  for (const raw of rawInstruments) {
    const t = raw.toUpperCase();
    if (!TICKER_REGEX.test(t)) { invalidInstruments.push(raw); continue; }
    if (seen.has(t)) continue;
    seen.add(t);
    instruments.push(t);
  }
  if (instruments.length === 0) {
    return { json: { _error: 'Keine gueltigen Instrumente angegeben.' + (invalidInstruments.length ? ' Ungueltig: ' + invalidInstruments.join(', ') : ''), sql: null } };
  }
  if (instruments.length > MAX_INSTRUMENTS) {
    return { json: { _error: 'Zu viele Instrumente (max ' + MAX_INSTRUMENTS + ').', sql: null } };
  }

  // Werktage Mo-Fr zwischen start/end enumerieren - der Worker ueberspringt Tage ohne echte
  // Kerzendaten selbst (Feiertage), hier nur die grobe Kalenderstruktur.
  const days = [];
  let cursor = new Date(startDate + 'T00:00:00Z');
  const end = new Date(endDate + 'T00:00:00Z');
  while (cursor <= end && days.length < 5000) {
    const dow = cursor.getUTCDay(); // 0=So, 6=Sa
    if (dow !== 0 && dow !== 6) days.push(cursor.toISOString().slice(0, 10));
    cursor = new Date(cursor.getTime() + 24 * 3600 * 1000);
  }
  if (days.length === 0) {
    return { json: { _error: 'Zeitraum enthaelt keine Werktage.', sql: null } };
  }

  const runIdHint = 'sim-' + getBusinessDate() + '-' + randHex(6);

  // Data-modifying CTE: new_run haelt genau 1 Zeile (die neu eingefuegte backtest_runs-Zeile
  // mit ihrer id). Die Tages-Schritte werden per CROSS JOIN mit dieser einen Zeile verknuepft -
  // die VALUES-Liste selbst enthaelt NUR (seq, day)-Tupel, new_run.id wird erst im SELECT
  // dazugemischt (new_run.id INNERHALB der VALUES-Tupel waere ungueltiges SQL, da VALUES keinen
  // Zugriff auf andere Tabellen/CTEs hat).
  const stepValues = days.map((day, idx) => `(${pgNum(idx + 1)}, ${pgStr(day)}::date)`).join(',\n    ');

  // Out-of-Sample-Ueberschneidungs-Sperre: dieselbe Strategie darf nicht zweimal ueber densel
  // ben (oder ueberlappenden) Zeitraum als OOS bestaetigt werden - sonst liesse sich ein
  // unerwuenschtes Ergebnis durch einfaches Wiederholen "wegwuerfeln" (p-hacking-Schutz).
  // Als WHERE-Klausel im INSERT SELECT statt eines separaten Pruef-Node, um im selben
  // Statement/derselben Transaktion atomar zu bleiben (kein zusaetzlicher Roundtrip noetig).
  sql = `BEGIN;
WITH new_run AS (
  INSERT INTO trading.backtest_runs
    (backtest_id, run_type, configuration_version, rule_version, status, data_category, name, start_date, end_date, current_simulation_date,
     timezone, instrument_selection_json, news_enabled, fundamentals_enabled, portfolio_enabled,
     learning_enabled, initial_capital, currency, progress_total, created_by, strategy_filter)
  SELECT ${pgStr(runIdHint)}, ${pgStr(runType)}, 'historische-simulation-v1', 'historische-simulation-v1', 'queued', 'historical_replay', ${pgStr(name)}, ${pgStr(startDate)}, ${pgStr(endDate)},
         ${pgStr(startDate)}, 'Europe/Berlin', ${pgJsonb(instruments)}, ${pgBool(newsEnabled)}, FALSE, TRUE, FALSE,
         ${pgNum(initialCapital)}, 'EUR', ${pgNum(days.length)}, 'simulation-steuerzentrale', ${pgStr(strategyFilter)}
  WHERE ${pgStr(runType)} <> 'out_of_sample' OR NOT EXISTS (
    SELECT 1 FROM trading.backtest_runs br2
    WHERE br2.run_type = 'out_of_sample' AND br2.strategy_filter = ${pgStr(strategyFilter)}
      AND br2.status IN ('queued','running','pausing','completed','completed_with_warnings')
      AND daterange(br2.start_date, br2.end_date, '[]') && daterange(${pgStr(startDate)}::date, ${pgStr(endDate)}::date, '[]')
  )
  RETURNING id
)
INSERT INTO trading.simulation_run_steps (simulation_run_id, sequence_number, simulated_date, status)
SELECT new_run.id, s.seq, s.day, 'pending'
FROM new_run, (VALUES\n    ${stepValues}\n) AS s(seq, day);
SELECT EXISTS(SELECT 1 FROM trading.backtest_runs WHERE backtest_id = ${pgStr(runIdHint)}) AS created;
COMMIT;`;

  responseInfo = { action, run_id_hint: runIdHint, day_count: days.length, instrument_count: instruments.length, invalid_instruments: invalidInstruments, run_type: runType, strategy_filter: strategyFilter };

} else if (action === 'pause') {
  const runId = String(body.run_id || '').trim();
  if (!runId) return { json: { _error: 'run_id fehlt.', sql: null } };
  sql = `BEGIN;\nUPDATE trading.backtest_runs SET status = 'pausing' WHERE id = ${pgNum(runId)} AND status IN ('queued','running');\nCOMMIT;`;
  responseInfo = { action, run_id: runId };

} else if (action === 'resume') {
  const runId = String(body.run_id || '').trim();
  if (!runId) return { json: { _error: 'run_id fehlt.', sql: null } };
  sql = `BEGIN;\nUPDATE trading.backtest_runs SET status = 'queued' WHERE id = ${pgNum(runId)} AND status = 'paused';\nCOMMIT;`;
  responseInfo = { action, run_id: runId };

} else if (action === 'cancel') {
  const runId = String(body.run_id || '').trim();
  if (!runId) return { json: { _error: 'run_id fehlt.', sql: null } };
  sql = `BEGIN;
UPDATE trading.backtest_runs SET status = 'cancelled', cancelled_at = now() WHERE id = ${pgNum(runId)} AND status IN ('draft','queued','running','pausing','paused');
UPDATE trading.simulation_run_steps SET status = 'skipped' WHERE simulation_run_id = ${pgNum(runId)} AND status IN ('pending','running');
COMMIT;`;
  responseInfo = { action, run_id: runId };
}

return { json: { sql, ...responseInfo } };

const original = $('POST: Formular normalisieren + SQL bauen').item.json;
const current = $json;

if (original._error) {
  return { json: { ok: false, error: original._error } };
}
if (current.error) {
  return { json: { ok: false, error: 'Datenbankfehler beim Ausfuehren der Aktion.', action: original.action } };
}
if (original.action === 'create_run' && current.created === false) {
  return { json: { ok: false, error: 'Abgelehnt: fuer die Strategie \'' + original.strategy_filter + '\' existiert bereits ein Out-of-Sample-Lauf mit ueberlappendem Zeitraum (queued/laufend/abgeschlossen) - kein erneuter Versuch ueber denselben Zeitraum.', action: original.action } };
}
return { json: { ok: true, action: original.action, run_id: original.run_id, run_id_hint: original.run_id_hint, day_count: original.day_count, instrument_count: original.instrument_count, invalid_instruments: original.invalid_instruments, run_type: original.run_type, strategy_filter: original.strategy_filter } };

// Gleiches Muster wie Workflow 15/16.
const items = $input.all().filter(i => i.json && i.json.id);
if (items.length === 0) {
  return [{ json: { _kein_run: true } }];
}
const run = items[0].json;
return [{ json: { ...run, _kein_run: false, _run_pausierend: run.status === 'pausing' } }];

// alwaysOutputData:true liefert bei 0 aktualisierten Zeilen (Lock nicht erhalten, ein anderer
// Tick bearbeitet diesen Lauf gerade) ein Platzhalter-Item ohne id.
const items = $input.all().filter(i => i.json && i.json.id !== undefined && i.json.id !== null);
return [{ json: { _lock_acquired: items.length > 0 } }];

// Traegt Lauf-Daten und Konfigurationswerte zusammen. Fehlende Config-Werte bekommen
// dieselben Standardwerte wie in 06/14 dokumentiert (falls noch nicht in pipeline_config
// vorhanden - sql/057 seedet nur die neuen SIMULATION_*-Schluessel, nicht die schon lange
// bestehenden 06/14-Schluessel, die aber i.d.R. schon aus fruaeheren Migrationen existieren).
const run = $('Pruefe Run-Zustand').all()[0].json;
const cfgRows = $input.all().map(i => i.json);
const cfgByKey = {};
for (const r of cfgRows) cfgByKey[r.config_key] = Number(r.value_numeric);

function num(key, fallback) {
  const v = cfgByKey[key];
  return (v !== undefined && v !== null && !isNaN(v)) ? v : fallback;
}

return [{ json: {
  ...run,
  _package_size: num('SIMULATION_DEFAULT_PACKAGE_SIZE', 20),
  _model_portfolio_value: num('MODEL_PORTFOLIO_VALUE', run.initial_capital || 100000),
  _max_risk_per_trade_pct: num('MAX_RISK_PER_TRADE_PCT', 1.0),
  _min_reward_risk_ratio: num('MIN_REWARD_RISK_RATIO', 1.5),
  _fees_bps: num('DEFAULT_FEES_BPS', 15),
  _slippage_bps: num('DEFAULT_SLIPPAGE_BPS', 10),
  _ambiguous_bar_policy_code: num('AMBIGUOUS_BAR_POLICY_CODE', 1),
  _max_total_open_risk_pct: num('MAX_TOTAL_OPEN_RISK_PCT', 6.0),
  _max_sector_exposure_pct: num('MAX_SECTOR_EXPOSURE_PCT', 15.0),
  _max_single_position_pct: num('MAX_SINGLE_POSITION_PCT', 8.0),
  _max_open_positions: num('MAX_OPEN_POSITIONS', 10),
  _max_directional_exposure_pct: num('MAX_DIRECTIONAL_EXPOSURE_PCT', 40.0),
  _max_region_exposure_pct: num('MAX_REGION_EXPOSURE_PCT', 60.0)
} }];

// Kein offenes Tages-Item mehr -> Lauf abschliessen (siehe Metriken-Zweig). Sonst: Paket
// weiterreichen.
const run = $('Baue Run-Kontext').all()[0].json;
const items = $input.all().map(i => i.json).filter(j => j && j.id !== undefined && j.id !== null);
if (items.length === 0) {
  return [{ json: { _placeholder: true, run_id: run.id } }];
}
return [{ json: { _placeholder: false, run_id: run.id, steps: items } }];

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

// Bestimmt den Preisdaten-Ladefenster-Bereich fuer dieses Paket (vom ersten Tag im Paket
// minus 400 Kalendertage, ausreichend Puffer fuer 252 Handelstage Lookback, bis zum letzten
// Tag im Paket) UND baut das SQL-Array-Literal fuer die Ticker-Liste EINMAL zentral (statt
// mehrfach inline in n8n-Expressions zu wiederholen, das ist fehleranfaelliger).
const pkt = $('Baue Paket-Kontext').all()[0].json;
const run = $('Baue Run-Kontext').all()[0].json;
const steps = pkt.steps;
const dates = steps.map(s => String(s.simulated_date).slice(0, 10)).sort();
const firstDay = dates[0];
const lastDay = dates[dates.length - 1];
const lookbackStart = new Date(new Date(firstDay + 'T00:00:00Z').getTime() - 400 * 24 * 3600 * 1000).toISOString().slice(0, 10);

const instruments = Array.isArray(run.instrument_selection_json) ? run.instrument_selection_json : [];
const tickerSqlArray = instruments.map(t => pgStr(t)).join(',');

return [{ json: { run_id: pkt.run_id, first_day: firstDay, last_day: lastDay, lookback_start: lookbackStart, _ticker_sql_array: tickerSqlArray } }];

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

function sma(values, period) {
  if (values.length < period) return null;
  const slice = values.slice(values.length - period);
  return slice.reduce((a, b) => a + b, 0) / period;
}
function stdev(values, period, mean) {
  if (values.length < period) return null;
  const slice = values.slice(values.length - period);
  const m = mean !== undefined ? mean : slice.reduce((a, b) => a + b, 0) / period;
  const variance = slice.reduce((a, b) => a + (b - m) * (b - m), 0) / period;
  return Math.sqrt(variance);
}
function emaSeries(values, period) {
  if (values.length < period) return [];
  const k = 2 / (period + 1);
  const out = [];
  let prev = values.slice(0, period).reduce((a, b) => a + b, 0) / period;
  out[period - 1] = prev;
  for (let i = period; i < values.length; i++) {
    prev = values[i] * k + prev * (1 - k);
    out[i] = prev;
  }
