  direction: o.direction, strategy: o.strategy, sektor: o.sektor, region: o.region || tickerToRegion[o.ticker] || 'global',
  entry_zone_low: Number(o.entry_zone_low), entry_zone_high: Number(o.entry_zone_high),
  stop_price: Number(o.stop_price), target_price: Number(o.target_price), time_stop_at: o.time_stop_at,
  risk_amount: Number(o.risk_amount), quantity: Number(o.quantity),
  theoretical_quantity: Number(o.theoretical_quantity), theoretical_risk_amount: Number(o.theoretical_risk_amount),
  clamp_reason: o.clamp_reason
}));

const steps = [...pktCtx.steps].sort((a, b) => a.sequence_number - b.sequence_number);

// SQL-Sammelstellen fuer das ganze Paket.
const orderUpdates = [];      // executed_price/execution_status auf simulation_orders
const newOrderRows = [];      // neue simulation_orders (naechster Handelstag)
const newTradeRows = [];      // neue simulation_trades (aus gefuellten Orders)
const tradeUpdates = [];      // Exit-Updates auf simulation_trades
const newRecRows = [];        // neue simulation_recommendations
const recCloseUpdates = [];   // status='geschlossen' auf simulation_recommendations
const positionRows = [];      // simulation_positions je Tag/Ticker
const portfolioRows = [];     // simulation_daily_portfolio je Tag
const stepCompletions = [];   // simulation_run_steps auf completed
const errorRows = [];         // simulation_errors bei Datenluecken

function nextWeekday(dateStr) {
  let d = new Date(dateStr + 'T00:00:00Z');
  d = new Date(d.getTime() + 24 * 3600 * 1000);
  while (d.getUTCDay() === 0 || d.getUTCDay() === 6) d = new Date(d.getTime() + 24 * 3600 * 1000);
  return d.toISOString().slice(0, 10);
}

for (const step of steps) {
  const day = String(step.simulated_date).slice(0, 10);
  const tickersToday = Object.keys(barsByTicker).filter(t => barOn(t, day) !== null);

  // --- 1. Ausstehende Orders mit faelliger Ausfuehrung pruefen ---
  const stillPending = [];
  for (const order of pendingOrders) {
    if (order.intended_execution_date > day) { stillPending.push(order); continue; }
    const bar = barOn(order.ticker, day);
    if (!bar) { stillPending.push(order); continue; } // Feiertag fuer dieses Instrument - naechster Tag erneut pruefen
    const fill = simulateEntryFill(order.entry_zone_low, order.entry_zone_high, bar);
    if (fill.filled) {
      const fee = fill.price * order.quantity * (cfg.feesBps / 10000);
      const slippage = fill.price * order.quantity * (cfg.slippageBps / 10000);
      const positionValue = fill.price * order.quantity;
      cash -= (positionValue + fee + slippage);
      const tradeId = 'trd-' + runId + '-' + order.db_id;
      orderUpdates.push({ id: order.db_id, status: 'filled', actual_execution_date: day, executed_price: fill.price, commission: fee, slippage_val: slippage });
      newTradeRows.push({
        trade_id: tradeId, order_id: order.db_id, ticker: order.ticker, strategy: order.strategy, direction: order.direction,
        as_of_date: day, entry_zone_low: order.entry_zone_low, entry_zone_high: order.entry_zone_high,
        entry_price: fill.price, stop_price: order.stop_price, target_price: order.target_price,
        time_stop_at: order.time_stop_at, quantity: order.quantity, risk_amount: order.risk_amount,
        theoretical_quantity: order.theoretical_quantity, theoretical_risk_amount: order.theoretical_risk_amount,
        clamp_reason: order.clamp_reason, sektor: order.sektor, region: order.region,
        position_value: positionValue, fee, slippage
      });
      openPositions.push({
        db_id: null, trade_id: tradeId, ticker: order.ticker, strategy: order.strategy, direction: order.direction,
        sektor: order.sektor, region: order.region, risk_amount: order.risk_amount, position_value: positionValue, quantity: order.quantity,
        stop_price: order.stop_price, target_price: order.target_price, time_stop_at: order.time_stop_at, is_new: true
      });
    } else {
      orderUpdates.push({ id: order.db_id, status: 'not_filled_price', actual_execution_date: day, executed_price: null, commission: 0, slippage_val: 0 });
      openRecTickers.delete(order.ticker);
    }
  }
  pendingOrders = stillPending;

  // --- 2. Signale fuer heute berechnen (fuer neue Kandidaten UND opposite_signal-Exit-Check) ---
  const signalsToday = {};
  for (const ticker of tickersToday) {
    const bars = barsUpTo(ticker, day);
    signalsToday[ticker] = computeSignals(bars, RULE_VERSION);
  }

  // --- 3. Exits fuer offene Positionen pruefen (inkl. heute frisch gefuellte - selbe-Kerze) ---
  const stillOpen = [];
  for (const pos of openPositions) {
    const bar = barOn(pos.ticker, day);
    if (!bar) { stillOpen.push(pos); continue; }
    const sig = signalsToday[pos.ticker];
    const oppositeSignal = sig && sig.signals.some(s => s.strategy === pos.strategy && s.direction !== pos.direction);
    const exitCheck = checkExit(pos, bar, day, ambiguousBarPolicyCode, oppositeSignal);
    if (exitCheck.exit) {
      const grossPnl = pos.direction === 'long' ? (exitCheck.price - (pos.position_value / pos.quantity)) * pos.quantity : ((pos.position_value / pos.quantity) - exitCheck.price) * pos.quantity;
      const exitNotional = exitCheck.price * pos.quantity;
      const exitFee = exitNotional * (cfg.feesBps / 10000);
      const exitSlippage = exitNotional * (cfg.slippageBps / 10000);
      const entryFee = pos.position_value * (cfg.feesBps / 10000);
      const entrySlippage = pos.position_value * (cfg.slippageBps / 10000);
      const netPnl = grossPnl - exitFee - exitSlippage - entryFee - entrySlippage;
      cash += (exitNotional - exitFee - exitSlippage);
      tradeUpdates.push({
        trade_id: pos.trade_id, db_id: pos.db_id, exit_time: day, exit_price: exitCheck.price, exit_reason: exitCheck.reason,
        gross_pnl: grossPnl, net_pnl: netPnl, r_multiple: pos.risk_amount > 0 ? netPnl / pos.risk_amount : null,
        commission_total: entryFee + exitFee, slippage_total: entrySlippage + exitSlippage, is_new: pos.is_new
      });
      recCloseUpdates.push({ ticker: pos.ticker, run_id: runId, exit_day: day });
      openRecTickers.delete(pos.ticker);
    } else {
      stillOpen.push(pos);
      positionRows.push({ ticker: pos.ticker, day, quantity: pos.quantity, cost_basis: pos.position_value / pos.quantity, mark_price: bar.close, unrealized_pnl: (pos.direction === 'long' ? (bar.close - pos.position_value / pos.quantity) : (pos.position_value / pos.quantity - bar.close)) * pos.quantity });
    }
  }
  openPositions = stillOpen;

  // --- 4. Neue Kandidaten pruefen (Positionsgroesse mit Kappung + verbleibende Haertegrenzen) ---
  for (const ticker of tickersToday) {
    if (openRecTickers.has(ticker)) continue; // schon offene Empfehlung/Position fuer diesen Ticker
    const sig = signalsToday[ticker];
    // Phase 6: Nachrichten VOR dem Leer-Check auswerten - WIDERSPRUECHLICHE_NEWS muss den
    // Ticker auch dann fuer den Tag blockieren, wenn technische Signale vorhanden waeren.
    const newsForTicker = (newsByTickerDate[ticker] && newsByTickerDate[ticker][day]) || [];
    if (newsForTicker.length && sig) {
      const newsEval = evaluateNewsForTicker(sig.signals, newsForTicker, sig.close, sig.atr, RULE_VERSION);
      if (newsEval.veto) continue;
      if (newsEval.candidate) sig.signals.push(newsEval.candidate);
    }
    // Phase 7: Out-of-Sample-Laeufe schraenken auf genau eine Strategie ein (09b bestaetigt
    // sonst keine einzelne Strategie, siehe strategy_filter-Kommentar im Formular-Handler) -
    // NACH dem News-Push filtern, damit ein Lauf mit strategy_filter='news_event' auch den
    // gerade erst hinzugefuegten News-Kandidaten sehen kann.
    if (sig && runCtx.strategy_filter) {
      sig.signals = sig.signals.filter(s => s.strategy === runCtx.strategy_filter);
    }
    if (!sig || !sig.signals.length) continue;
    const best = sig.signals.reduce((a, b) => (b.raw_score > a.raw_score ? b : a));
    const bar = barOn(ticker, day);
    const sektor = tickerToSektor[ticker] || 'unbekannt';
    const region = tickerToRegion[ticker] || 'global';
    const sizing = sizePosition(best, bar.close, cfg, openPositions, sektor, region);
    if (sizing.veto) continue;
    const hardBlockers = checkHardLimits(best.direction, sizing.position_value, openPositions, cfg);
    if (hardBlockers.length > 0) continue;

    const nextDay = nextWeekday(day);
    const timeStopAt = new Date(new Date(day + 'T00:00:00Z').getTime() + best.expected_horizon_days * 24 * 3600 * 1000).toISOString();

    newRecRows.push({ run_id: runId, as_of_date: day, ticker, direction: best.direction, strategy: best.strategy, entry_grund: best.evidence.join('; ') + (sizing.clamped ? ` [gekappt: ${sizing.clamp_reason}]` : '') });
    newOrderRows.push({
      run_id: runId, ticker, signal_date: day, intended_execution_date: nextDay, direction: best.direction,
      strategy: best.strategy, sektor, region, entry_zone_low: best.entry_zone_low, entry_zone_high: best.entry_zone_high,
      stop_price: best.stop_price, target_price: best.target_price, time_stop_at: timeStopAt,
      risk_amount: sizing.actual_risk_amount, theoretical_risk_amount: sizing.theoretical_risk_amount,
      quantity: sizing.actual_quantity, theoretical_quantity: sizing.theoretical_quantity,
      clamp_reason: sizing.clamp_reason, limit_price: bar.close
    });
    // Sofort in den lokalen Zustand aufnehmen (wie 14 Job A: bereits genehmigte Kandidaten
    // zaehlen fuer die Pruefung nachfolgender Kandidaten DESSELBEN Tages mit).
    openPositions.push({ db_id: null, trade_id: null, ticker, strategy: best.strategy, direction: best.direction, sektor, region, risk_amount: sizing.actual_risk_amount, position_value: sizing.position_value, quantity: sizing.actual_quantity, stop_price: best.stop_price, target_price: best.target_price, time_stop_at: timeStopAt, is_new: false, _pending_only: true });
    openRecTickers.add(ticker);
  }
  // Nur-Order-Kandidaten (noch nicht gefuellt) wieder aus openPositions entfernen - die zaehlen
  // fuer die Risikopruefung INNERHALB desselben Tages, aber nicht als echte offene Position
  // fuer den naechsten Tag (sie sind ja noch nicht ausgefuehrt).
  openPositions = openPositions.filter(p => !p._pending_only);

  // --- 5. Tages-Portfolio-Zeile ---
  const positionsValue = openPositions.reduce((sum, p) => {
    const bar = barOn(p.ticker, day);
    if (!bar) return sum + p.position_value;
    const markValue = p.direction === 'long' ? bar.close * p.quantity : (2 * (p.position_value / p.quantity) - bar.close) * p.quantity;
    return sum + markValue;
  }, 0);
  const totalEquity = cash + positionsValue;
  if (totalEquity > peakEquity) peakEquity = totalEquity;
  const drawdownPct = peakEquity > 0 ? (peakEquity - totalEquity) / peakEquity * 100 : 0;
  portfolioRows.push({ day, cash, positions_value: positionsValue, total_equity: totalEquity, drawdown_pct: drawdownPct, open_positions_count: openPositions.length });

  stepCompletions.push(step.id);
}

return [{ json: {
  run_id: runId, orderUpdates, newOrderRows, newTradeRows, tradeUpdates, newRecRows, recCloseUpdates,
  positionRows, portfolioRows, stepCompletions, lastDay: steps.length ? String(steps[steps.length - 1].simulated_date).slice(0, 10) : null
} }];

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

// Uebersetzt die strukturierte Ausgabe von "Verarbeite Tage-Paket" in ein einziges grosses
// SQL-Transaktions-Statement (gleiches Muster wie Workflow 15/16: ein Code-Node baut alles,
// ein Postgres-Node fuehrt es aus).
const r = $json;
const runId = r.run_id;
const parts = [];

const RICHTUNG = { long: 'kauf', short: 'verkauf' };

for (const u of r.orderUpdates) {
  parts.push(`UPDATE trading.simulation_orders SET execution_status = ${pgStr(u.status)}, actual_execution_date = ${pgStr(u.actual_execution_date)}, executed_price = ${pgNum(u.executed_price)}, commission = ${pgNum(u.commission)}, slippage = ${pgNum(u.slippage_val)} WHERE id = ${pgNum(u.id)};`);
}

for (const o of r.newOrderRows) {
  parts.push(`INSERT INTO trading.simulation_orders
    (simulation_run_id, ticker, signal_date, order_created_at, intended_execution_date, order_type, limit_price, quantity, theoretical_quantity, execution_status, direction, strategy, sektor, region, entry_zone_low, entry_zone_high, stop_price, target_price, time_stop_at, risk_amount, theoretical_risk_amount, clamp_reason, rule_version)
    VALUES (${pgNum(runId)}, ${pgStr(o.ticker)}, ${pgStr(o.signal_date)}, ${pgStr(o.signal_date + 'T22:00:00Z')}, ${pgStr(o.intended_execution_date)}, 'limit', ${pgNum(o.limit_price)}, ${pgNum(o.quantity)}, ${pgNum(o.theoretical_quantity)}, 'pending', ${pgStr(o.direction)}, ${pgStr(o.strategy)}, ${pgStr(o.sektor)}, ${pgStr(o.region)}, ${pgNum(o.entry_zone_low)}, ${pgNum(o.entry_zone_high)}, ${pgNum(o.stop_price)}, ${pgNum(o.target_price)}, ${pgStr(o.time_stop_at)}, ${pgNum(o.risk_amount)}, ${pgNum(o.theoretical_risk_amount)}, ${pgStr(o.clamp_reason)}, 'historische-simulation-v1');`);
}

for (const t of r.newTradeRows) {
  parts.push(`INSERT INTO trading.simulation_trades
    (trade_id, simulation_run_id, simulation_order_id, ticker, strategy, direction, as_of_date, signal_created_at, decision_time, entry_rule, planned_entry_zone_low, planned_entry_zone_high, simulated_entry_time, simulated_entry_price, stop_price_initial, target_price_initial, stop_price_current, time_stop_at, actual_quantity, theoretical_quantity, risk_amount, theoretical_risk_amount, clamp_reason, sektor, region, position_value, commission_total, slippage_total, data_schema_version, rule_version, status)
    VALUES (${pgStr(t.trade_id)}, ${pgNum(runId)}, ${pgNum(t.order_id)}, ${pgStr(t.ticker)}, ${pgStr(t.strategy)}, ${pgStr(t.direction)}, ${pgStr(t.as_of_date)}, ${pgStr(t.as_of_date + 'T22:00:00Z')}, ${pgStr(t.as_of_date + 'T22:00:00Z')}, 'zone_fill', ${pgNum(t.entry_zone_low)}, ${pgNum(t.entry_zone_high)}, ${pgStr(t.as_of_date + 'T00:00:00Z')}, ${pgNum(t.entry_price)}, ${pgNum(t.stop_price)}, ${pgNum(t.target_price)}, ${pgNum(t.stop_price)}, ${pgStr(t.time_stop_at)}, ${pgNum(t.quantity)}, ${pgNum(t.theoretical_quantity)}, ${pgNum(t.risk_amount)}, ${pgNum(t.theoretical_risk_amount)}, ${pgStr(t.clamp_reason)}, ${pgStr(t.sektor)}, ${pgStr(t.region)}, ${pgNum(t.position_value)}, ${pgNum(t.fee)}, ${pgNum(t.slippage)}, 'historische-simulation-v1', 'historische-simulation-v1', 'open')
    ON CONFLICT (simulation_run_id, trade_id) DO NOTHING;`);
}

for (const u of r.tradeUpdates) {
  parts.push(`UPDATE trading.simulation_trades SET
    status = 'closed', exit_time = ${pgStr(u.exit_time + 'T22:00:00Z')}, exit_price = ${pgNum(u.exit_price)},
    exit_reason = ${pgStr(u.exit_reason)}, gross_pnl = ${pgNum(u.gross_pnl)}, net_pnl = ${pgNum(u.net_pnl)},
    realized_r_multiple = ${pgNum(u.r_multiple)}, holding_period_days = ${pgStr(u.exit_time)}::date - as_of_date,
    commission_total = ${pgNum(u.commission_total)}, slippage_total = ${pgNum(u.slippage_total)}, updated_at = now()
    WHERE simulation_run_id = ${pgNum(runId)} AND trade_id = ${pgStr(u.trade_id)};`);
}

for (const rec of r.newRecRows) {
  parts.push(`INSERT INTO trading.simulation_recommendations
    (simulation_run_id, as_of_date, ticker, richtung, status, strategy, entry_grund, entry_datum, rule_version)
    VALUES (${pgNum(runId)}, ${pgStr(rec.as_of_date)}, ${pgStr(rec.ticker)}, ${pgStr(RICHTUNG[rec.direction] || 'kauf')}, 'offen', ${pgStr(rec.strategy)}, ${pgStr(rec.entry_grund)}, ${pgStr(rec.as_of_date)}, 'historische-simulation-v1')
    ON CONFLICT (simulation_run_id, ticker) WHERE status = 'offen' DO NOTHING;`);
}

for (const c of r.recCloseUpdates) {
  parts.push(`UPDATE trading.simulation_recommendations SET status = 'geschlossen', exit_datum = ${pgStr(c.exit_day)} WHERE simulation_run_id = ${pgNum(c.run_id)} AND ticker = ${pgStr(c.ticker)} AND status = 'offen';`);
}

for (const p of r.positionRows) {
  parts.push(`INSERT INTO trading.simulation_positions
    (simulation_run_id, ticker, simulated_date, quantity, average_cost_basis, mark_price, unrealized_pnl)
    VALUES (${pgNum(runId)}, ${pgStr(p.ticker)}, ${pgStr(p.day)}, ${pgNum(p.quantity)}, ${pgNum(p.cost_basis)}, ${pgNum(p.mark_price)}, ${pgNum(p.unrealized_pnl)})
    ON CONFLICT (simulation_run_id, ticker, simulated_date) DO UPDATE SET quantity = EXCLUDED.quantity, average_cost_basis = EXCLUDED.average_cost_basis, mark_price = EXCLUDED.mark_price, unrealized_pnl = EXCLUDED.unrealized_pnl;`);
}

for (const p of r.portfolioRows) {
  parts.push(`INSERT INTO trading.simulation_daily_portfolio
    (simulation_run_id, simulated_date, cash, positions_value, total_equity, drawdown_pct, open_positions_count)
    VALUES (${pgNum(runId)}, ${pgStr(p.day)}, ${pgNum(p.cash)}, ${pgNum(p.positions_value)}, ${pgNum(p.total_equity)}, ${pgNum(p.drawdown_pct)}, ${pgNum(p.open_positions_count)})
    ON CONFLICT (simulation_run_id, simulated_date) DO UPDATE SET cash = EXCLUDED.cash, positions_value = EXCLUDED.positions_value, total_equity = EXCLUDED.total_equity, drawdown_pct = EXCLUDED.drawdown_pct, open_positions_count = EXCLUDED.open_positions_count;`);
}

if (r.stepCompletions.length > 0) {
  const ids = r.stepCompletions.map(id => pgNum(id)).join(',');
  parts.push(`UPDATE trading.simulation_run_steps SET status = 'completed', finished_at = now(), heartbeat_at = now() WHERE id IN (${ids});`);
}

parts.push(`UPDATE trading.backtest_runs SET
  progress_completed = (SELECT count(*) FROM trading.simulation_run_steps WHERE simulation_run_id = ${pgNum(runId)} AND status = 'completed'),
  progress_percent = (SELECT round(100.0 * count(*) FILTER (WHERE status = 'completed') / GREATEST(count(*), 1), 2) FROM trading.simulation_run_steps WHERE simulation_run_id = ${pgNum(runId)}),
  current_simulation_date = ${pgStr(r.lastDay)}, last_heartbeat = now()
  WHERE id = ${pgNum(runId)};`);

const sql = `BEGIN;\n${parts.join('\n')}\nCOMMIT;`;
return [{ json: { sql, run_id: runId } }];
